-- =============================================================================
-- Guided customer onboarding (master plan §12 B68, docs/ONBOARDING.md §4).
--
-- One onboarding checklist per company, generated by the database from what it knows about the company: its plan
-- (or demo plan), fleet (trucks, tractors, trailers, drivers), dispatch bases, the customer portal entitlement and the
-- integrations the server reports as configured. Generation only ever adds missing tasks; it never removes a task or
-- changes a status.
--
--   * public.onboarding_tasks: title, instructions, who acts (customer / Taviron / shared), whether Taviron must review,
--     dependencies (task keys), assignee and due date, and one of eight states:
--       not_started, in_progress, awaiting_customer, submitted, changes_requested, approved, blocked, not_applicable.
--   * public.onboarding_events: append-only history (status changes, comments, documents, assignments, reminders,
--     imports). Taviron's internal notes are never shown to the company.
--   * public.onboarding_documents: private files (PDF, JPEG, PNG, CSV up to 10 MB) on a task, in the private Storage
--     bucket `onboarding-documents` at a path the database chooses (same model as communication attachments).
--
-- Who may do what (enforced here, again in the app):
--   * Company side: people with settings.manage in that company, on tasks the customer acts on. They may start, submit
--     for review, withdraw a submission, mark blocked (with a reason), comment, assign and upload. They complete a task
--     themselves only when it needs no review. They never approve a reviewed task, set "not applicable" or reopen a
--     finished one.
--   * Taviron side: platform administrators (private.require_platform_admin(): admin and, unless the database owner
--     switched it off, an aal2 session). They approve, request changes, set awaiting customer / not applicable /
--     blocked (with a reason) and reopen.
--   * Approving or completing a task needs every task it depends on to be approved or not applicable.
--   * Onboarding never changes the lifecycle: no function here touches private.company_lifecycle (go-live date, stage,
--     fees) or billing. Completing every task is information for the go-live review, not a go-live.
--   * Reminders and notices are in-app notifications only (private.comm_notify, new category 'onboarding'); nothing is
--     emailed. Demo companies get sample tasks through public.onboarding_demo_samples() (is_demo only).
--
-- Depends on 20261105000100 (comm_notifications, comm_notify), 20261118000300 (company_lifecycle, plan versions),
-- 20261120000100 (dispatch_bases, demo_plan), 20261120000700 (portal entitlements), 20261120000900 (aal2 in
-- require_platform_admin).
-- Rollback: supabase/rollbacks/20261120001000_guided_onboarding.down.sql
-- =============================================================================

create table public.onboarding_tasks (
  id               uuid primary key default gen_random_uuid(),
  company_id       uuid not null references public.companies (id),
  key              text not null check (key ~ '^[a-z][a-z0-9_]{1,39}$'),
  title            text not null check (length(btrim(title)) between 1 and 120),
  instructions     text not null default '' check (length(instructions) <= 2000),
  category         text not null check (category in ('account', 'people', 'data', 'fleet', 'bases', 'modules', 'integrations', 'training', 'go_live')),
  side             text not null check (side in ('customer', 'taviron', 'shared')),
  review_required  boolean not null default true,
  required         boolean not null default true,
  readiness_id     text check (readiness_id in ('company', 'users', 'customers', 'materials', 'trucks', 'trailers', 'drivers')),
  import_entity    text check (import_entity in ('customers', 'materials', 'trucks', 'drivers')),
  depends_on       text[] not null default '{}',
  sort             integer not null default 0,
  status           text not null default 'not_started' check (status in ('not_started', 'in_progress', 'awaiting_customer', 'submitted',
                                                                         'changes_requested', 'approved', 'blocked', 'not_applicable')),
  status_note      text not null default '' check (length(status_note) <= 1000),
  assignee         uuid references auth.users (id) on delete set null,
  due_on           date,
  submitted_at     timestamptz,
  submitted_by     uuid references auth.users (id) on delete set null,
  decided_at       timestamptz,
  decided_by       uuid references auth.users (id) on delete set null,
  last_reminded_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (company_id, key),
  unique (company_id, id)
);
create index onboarding_tasks_open_idx on public.onboarding_tasks (company_id, status);

create trigger a_company_guard before update of company_id on public.onboarding_tasks
  for each row execute function private.forbid_company_change();

create table public.onboarding_events (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references public.companies (id),
  task_id     uuid not null,
  actor       uuid references auth.users (id) on delete set null,
  actor_side  text not null check (actor_side in ('customer', 'taviron', 'system')),
  kind        text not null check (kind in ('created', 'status', 'comment', 'document', 'assigned', 'reminder', 'import')),
  from_status text,
  to_status   text,
  body        text not null default '' check (length(body) <= 2000),
  internal    boolean not null default false,
  created_at  timestamptz not null default clock_timestamp(),
  constraint onboarding_events_task_fk foreign key (company_id, task_id) references public.onboarding_tasks (company_id, id) on delete cascade,
  check (not internal or actor_side = 'taviron')
);
create index onboarding_events_task_idx on public.onboarding_events (task_id, created_at);

create or replace function private.onboarding_events_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Onboarding history cannot be changed.' using errcode = '42501';
end;
$$;
create trigger onboarding_events_append_only before update on public.onboarding_events
  for each row execute function private.onboarding_events_append_only();

create table public.onboarding_documents (
  id           uuid primary key default gen_random_uuid(),
  company_id   uuid not null references public.companies (id),
  task_id      uuid not null,
  status       text not null default 'pending' check (status in ('pending', 'uploaded', 'discarded')),
  object_path  text not null unique check (object_path ~ '^[0-9a-f-]{36}/onboarding/[0-9a-f-]{36}\.(pdf|jpg|png|csv)$'),
  file_name    text not null check (length(trim(file_name)) between 1 and 200),
  mime_type    text not null check (mime_type in ('application/pdf', 'image/jpeg', 'image/png', 'text/csv')),
  size_bytes   integer not null check (size_bytes between 1 and 10485760),
  sha256       text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  upload_key   uuid not null,
  side         text not null check (side in ('customer', 'taviron')),
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  uploaded_at  timestamptz,
  unique (company_id, upload_key),
  constraint onboarding_documents_path_company check (split_part(object_path, '/', 1) = company_id::text),
  constraint onboarding_documents_task_fk foreign key (company_id, task_id) references public.onboarding_tasks (company_id, id) on delete cascade,
  check ((status = 'uploaded') = (uploaded_at is not null))
);
create index onboarding_documents_task_idx on public.onboarding_documents (task_id) where status = 'uploaded';

create trigger a_company_guard before update of company_id on public.onboarding_documents
  for each row execute function private.forbid_company_change();

-- Reads: the company's settings.manage people see their own company's tasks, the non-internal history and uploaded
-- documents. Writes only through the functions below. Taviron reads through platform_onboarding().
alter table public.onboarding_tasks enable row level security;
alter table public.onboarding_events enable row level security;
alter table public.onboarding_documents enable row level security;
create policy onboarding_tasks_read on public.onboarding_tasks for select to authenticated
  using (company_id = (select private.current_company_id()) and (select private.has_permission('settings.manage')));
create policy onboarding_events_read on public.onboarding_events for select to authenticated
  using (company_id = (select private.current_company_id()) and not internal and (select private.has_permission('settings.manage')));
create policy onboarding_documents_read on public.onboarding_documents for select to authenticated
  using (company_id = (select private.current_company_id()) and status = 'uploaded' and (select private.has_permission('settings.manage')));
revoke all on public.onboarding_tasks, public.onboarding_events, public.onboarding_documents from anon, authenticated;
grant select on public.onboarding_tasks, public.onboarding_events, public.onboarding_documents to authenticated;
grant all on public.onboarding_tasks, public.onboarding_events, public.onboarding_documents to service_role;

-- In-app notifications get an 'onboarding' category (no preference switch: these are few and addressed to a person).
alter table public.comm_notifications drop constraint comm_notifications_category_check;
alter table public.comm_notifications add constraint comm_notifications_category_check
  check (category in ('direct', 'group', 'channel', 'announcement', 'alert', 'catch_up', 'membership', 'onboarding'));

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------

/** Is the caller a platform administrator with the assurance the platform console requires (no raise)? */
create or replace function private.onboarding_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_platform_admin() and (private.aal2() or not private.platform_mfa_enforced());
$$;
revoke all on function private.onboarding_staff() from public, anon, authenticated;

/** May the caller act for the company side of this company (settings.manage in it, as their current company)? */
create or replace function private.onboarding_customer(p_company uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_company = private.current_company_id() and private.has_permission('settings.manage');
$$;
revoke all on function private.onboarding_customer(uuid) from public, anon, authenticated;

/** Keys of this task's dependencies that are not yet approved or not applicable. */
create or replace function private.onboarding_unmet(p_task public.onboarding_tasks)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(d.title order by d.sort), '{}')
  from public.onboarding_tasks d
  where d.company_id = p_task.company_id and d.key = any (p_task.depends_on) and d.status not in ('approved', 'not_applicable');
$$;
revoke all on function private.onboarding_unmet(public.onboarding_tasks) from public, anon, authenticated;

/** In-app notice to the task's assignee, or else to the company's active owners. Never email. */
create or replace function private.onboarding_notify(p_task public.onboarding_tasks, p_title text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
  v_n integer := 0;
begin
  for v_user in
    select m.user_id from public.company_memberships m
    where m.company_id = p_task.company_id and m.active
      and (m.user_id = p_task.assignee or (p_task.assignee is null and m.role = 'owner'))
  loop
    perform private.comm_notify(p_task.company_id, v_user, 'onboarding', p_title, '/setup#task-' || p_task.key, null, p_task.id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;
revoke all on function private.onboarding_notify(public.onboarding_tasks, text) from public, anon, authenticated;

/** Counts for dashboards: required tasks done, waiting on the customer, waiting on Taviron's review, blocked, overdue. */
create or replace function private.onboarding_summary(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'total', count(*),
    'required', count(*) filter (where required),
    'required_done', count(*) filter (where required and status in ('approved', 'not_applicable')),
    'done', count(*) filter (where status in ('approved', 'not_applicable')),
    'customer_actions', count(*) filter (where side <> 'taviron' and status in ('not_started', 'in_progress', 'awaiting_customer', 'changes_requested')),
    'review', count(*) filter (where status = 'submitted'),
    'blocked', count(*) filter (where status = 'blocked'),
    'overdue', count(*) filter (where due_on < private.company_today(p_company) and status not in ('approved', 'not_applicable')),
    'ready', count(*) > 0 and count(*) filter (where required and status not in ('approved', 'not_applicable')) = 0)
  from public.onboarding_tasks where company_id = p_company;
$$;
revoke all on function private.onboarding_summary(uuid) from public, anon, authenticated;

/** The company's checklist as JSON. Internal notes only for Taviron. */
create or replace function private.onboarding_json(p_company uuid, p_staff boolean)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'company_id', p_company,
    'tasks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'key', t.key, 'title', t.title, 'instructions', t.instructions, 'category', t.category, 'side', t.side,
        'review_required', t.review_required, 'required', t.required, 'readiness_id', t.readiness_id, 'import_entity', t.import_entity,
        'depends_on', t.depends_on, 'unmet', private.onboarding_unmet(t), 'status', t.status, 'status_note', t.status_note,
        'assignee', t.assignee, 'assignee_name', (select coalesce(nullif(p.display_name, ''), p.full_name) from public.profiles p where p.id = t.assignee),
        'due_on', t.due_on, 'submitted_at', t.submitted_at, 'decided_at', t.decided_at, 'last_reminded_at', t.last_reminded_at,
        'updated_at', t.updated_at,
        'documents', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'file_name', d.file_name, 'mime_type', d.mime_type,
            'size_bytes', d.size_bytes, 'side', d.side, 'uploaded_at', d.uploaded_at) order by d.uploaded_at)
          from public.onboarding_documents d where d.task_id = t.id and d.status = 'uploaded'), '[]'::jsonb),
        'events', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'actor_side', e.actor_side,
            'actor_name', (select coalesce(nullif(p.display_name, ''), p.full_name) from public.profiles p where p.id = e.actor),
            'from_status', e.from_status, 'to_status', e.to_status, 'body', e.body, 'internal', e.internal, 'created_at', e.created_at)
            order by e.created_at)
          from public.onboarding_events e where e.task_id = t.id and (p_staff or not e.internal)), '[]'::jsonb)
      ) order by t.sort, t.title) from public.onboarding_tasks t where t.company_id = p_company), '[]'::jsonb),
    'summary', private.onboarding_summary(p_company));
$$;
revoke all on function private.onboarding_json(uuid, boolean) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Generation
-- -----------------------------------------------------------------------------

/**
 * Add the tasks this company's situation calls for and that it does not have yet. Never removes a task, never changes
 * a status; a task still not started gets its instructions refreshed (counts and plan limits change). p_integrations
 * holds what the server knows is configured: {"routing": bool, "ai": bool}. Returns the number of tasks added.
 */
create or replace function private.onboarding_generate(p_company uuid, p_integrations jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_plan_name text;
  v_plan_trucks integer;
  v_plan_bases integer;
  v_trucks integer;
  v_tractors integer;
  v_trailers integer;
  v_drivers integer;
  v_bases integer;
  v_portal boolean;
  v_routing boolean := coalesce((p_integrations ->> 'routing')::boolean, false);
  v_ai boolean := coalesce((p_integrations ->> 'ai')::boolean, false);
  v_plan_line text;
  v_added integer := 0;
  r record;
begin
  if not exists (select 1 from public.companies where id = p_company) then
    raise exception 'Company not found.' using errcode = 'P0002';
  end if;

  select v.name, v.trucks, v.bases into v_plan_name, v_plan_trucks, v_plan_bases
  from private.company_lifecycle l join private.platform_plan_versions v on v.id = l.plan_version_id
  where l.company_id = p_company;
  if v_plan_name is null then
    select v.name, v.trucks, v.bases into v_plan_name, v_plan_trucks, v_plan_bases
    from public.companies c join private.platform_plan_versions v on v.plan_key = c.demo_plan
    where c.id = p_company order by v.version desc limit 1;
  end if;
  select count(*) filter (where truck_type <> 'tractor'), count(*) filter (where truck_type = 'tractor')
    into v_trucks, v_tractors from public.trucks where company_id = p_company and active;
  select count(*) into v_trailers from public.trailers where company_id = p_company and active;
  select count(*) into v_drivers from public.drivers where company_id = p_company and active;
  select count(*) into v_bases from public.dispatch_bases where company_id = p_company and active;
  v_portal := coalesce((select entitled from private.portal_entitlements where company_id = p_company), false);
  v_plan_line := case when v_plan_name is null then 'No plan is recorded for this company yet.'
                      else format('Plan: %s%s.', v_plan_name, case when v_plan_trucks is null then '' else format(' (up to %s trucks)', v_plan_trucks) end) end;

  for r in
    select * from (values
      (10, 'agreement', 'Agreement and onboarding fee', 'account', 'taviron', false, true, null::text, null::text, '{}'::text[],
       'Taviron confirms the signed service agreement and the onboarding fee (received or waived) on the company''s lifecycle page. ' ||
       'Marking this task does not change billing or the go-live date.', true),
      (20, 'company_profile', 'Complete your company profile', 'account', 'customer', false, true, 'company', null, '{}',
       'Settings → Company: address, phone or email and time zone. Quotes, documents and "today" use these details.', true),
      (30, 'people', 'Invite your team and choose their roles', 'people', 'customer', false, true, 'users', null, '{}',
       'People → Invite: add the people who dispatch, review tickets and bill. Each person sees what their role allows.', true),
      (40, 'customers', 'Send your customer list', 'data', 'customer', true, true, 'customers', 'customers', '{}',
       'Upload a CSV of your customers (name, billing address, email, phone) to this task, or add them under Customers. ' ||
       'Taviron checks the file, shows you any duplicates or errors, and imports only after review.', true),
      (50, 'materials', 'Send your materials and standard rates', 'data', 'customer', true, true, 'materials', 'materials', '{}',
       'Upload a CSV of materials with unit and standard rate, or add them under Materials. A material without a rate cannot be priced.', true),
      (60, 'trucks', 'Confirm your trucks and their capacity', 'fleet', 'customer', true, true, 'trucks', 'trucks', '{}',
       format('Upload a CSV of trucks (unit number, type, weight or volume capacity) or add them under Fleet. Taviron counts %s active %s today. %s',
              v_trucks, case when v_trucks = 1 then 'truck' else 'trucks' end, v_plan_line), true),
      (65, 'trailers', 'Confirm your trailers', 'fleet', 'customer', true, true, 'trailers', null, '{}',
       format('%s tractor(s) and %s trailer(s) recorded. A tractor is dispatched only with a compatible trailer: record each trailer''s capacity and the truck types it fits.',
              v_tractors, v_trailers), v_tractors > 0 or v_trailers > 0),
      (70, 'drivers', 'Send your drivers and their qualifications', 'fleet', 'customer', true, true, 'drivers', 'drivers', '{}',
       format('Upload a CSV of drivers (name, phone, CDL class and expiry, medical card expiry) or add them under Fleet → Drivers. %s active driver(s) recorded. ' ||
              'Taviron never dispatches a driver without a valid, verified CDL and medical card.', v_drivers), true),
      (80, 'bases', 'Set up each dispatch base', 'bases', 'customer', true, true, null, null, '{}',
       format('Settings → Bases: one record per yard you dispatch from, with its address. %s active base(s) recorded%s.',
              v_bases, case when v_plan_bases is null then '' else format('; your plan includes up to %s', v_plan_bases) end),
       coalesce(v_plan_bases, 1) > 1 or v_bases > 1),
      (85, 'yard_location', 'Pin your yard for route planning', 'integrations', 'customer', false, false, null, null, '{}',
       'Settings → Company: confirm the yard location on the map so route estimates start from the right place.', v_routing),
      (90, 'portal', 'Set up your customer portal', 'modules', 'customer', false, false, null, null, '{}',
       'Customer portal: choose what your customers can see, add your hours and welcome text, then invite your first customer contacts. ' ||
       'Nothing is sent until you invite someone.', v_portal),
      (95, 'ai_review', 'Review the AI capabilities', 'integrations', 'customer', false, false, null, null, '{}',
       'Company setup → AI capabilities: each feature shows whether it is ready. AI suggestions are labelled and never approve or change anything on their own.', v_ai),
      (100, 'import_review', 'Taviron reviews and imports your records', 'data', 'taviron', false, true, null, null,
       array['customers', 'materials', 'trucks', 'drivers'],
       'Taviron stages each file, shows rows that are ready, possible duplicates or need fixing, and creates records only after an explicit approval. ' ||
       'An approved import can be reverted while nothing uses its records.', true),
      (110, 'training_dispatch', 'Dispatcher training session', 'training', 'shared', true, true, null, null, array['trucks', 'drivers'],
       'A session with your dispatchers on the Dispatch board, Plan the day and Smart Dispatch suggestions (which only propose; a dispatcher approves).', true),
      (120, 'training_office', 'Office and billing training session', 'training', 'shared', true, true, null, null, array['customers', 'materials'],
       'A session with your office team on quotes, orders, delivery tickets and invoice drafts (drafts are previews; nothing is issued automatically).', true),
      (200, 'go_live_review', 'Go-live readiness review', 'go_live', 'taviron', false, true, null, null,
       array['agreement', 'company_profile', 'people', 'customers', 'materials', 'trucks', 'drivers', 'import_review', 'training_dispatch', 'training_office'],
       'Taviron confirms every required task is approved or not applicable, then agrees the go-live date with you on the lifecycle page. ' ||
       'Completing onboarding never changes an agreed go-live date and never starts billing.', true)
    ) as x(sort, key, title, category, side, review_required, required, readiness_id, import_entity, depends_on, instructions, applies)
  loop
    continue when not r.applies;
    insert into public.onboarding_tasks (company_id, key, title, instructions, category, side, review_required, required, readiness_id, import_entity, depends_on, sort)
    values (p_company, r.key, r.title, r.instructions, r.category, r.side, r.review_required, r.required, r.readiness_id, r.import_entity, r.depends_on, r.sort)
    on conflict (company_id, key) do update set instructions = excluded.instructions, updated_at = now()
      where public.onboarding_tasks.status = 'not_started' and public.onboarding_tasks.instructions is distinct from excluded.instructions;
    if not exists (select 1 from public.onboarding_events e join public.onboarding_tasks t on t.id = e.task_id
                   where t.company_id = p_company and t.key = r.key and e.kind = 'created') then
      insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, to_status, body)
      select p_company, t.id, auth.uid(), 'system', 'created', t.status, 'Added to the onboarding checklist.'
      from public.onboarding_tasks t where t.company_id = p_company and t.key = r.key;
      v_added := v_added + 1;
    end if;
  end loop;
  -- Dependencies only on tasks this company has (a fleet without trailers has no trailers task).
  update public.onboarding_tasks t set depends_on = coalesce((select array_agg(k) from unnest(t.depends_on) k
      where exists (select 1 from public.onboarding_tasks o where o.company_id = p_company and o.key = k)), '{}')
  where t.company_id = p_company
    and exists (select 1 from unnest(t.depends_on) k where not exists (select 1 from public.onboarding_tasks o where o.company_id = p_company and o.key = k));
  return v_added;
end;
$$;
revoke all on function private.onboarding_generate(uuid, jsonb) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Status changes (one rule set for both sides)
-- -----------------------------------------------------------------------------

create or replace function private.onboarding_change(p_task uuid, p_status text, p_note text, p_staff boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  v_note text := left(btrim(coalesce(p_note, '')), 1000);
  v_unmet text[];
  v_side text := case when p_staff then 'taviron' else 'customer' end;
begin
  select * into t from public.onboarding_tasks where id = p_task for update;
  if not found or (not p_staff and not private.onboarding_customer(t.company_id)) then
    raise exception 'Task not found.' using errcode = 'P0002';
  end if;
  if p_status is null or p_status not in ('not_started', 'in_progress', 'awaiting_customer', 'submitted', 'changes_requested', 'approved', 'blocked', 'not_applicable') then
    raise exception 'Unknown status.' using errcode = '22023';
  end if;
  if p_status = t.status then
    return jsonb_build_object('id', t.id, 'status', t.status, 'changed', false);
  end if;

  if not p_staff then
    if t.side = 'taviron' then
      raise exception 'Taviron completes this task. You can comment on it.' using errcode = '42501';
    end if;
    if t.status in ('approved', 'not_applicable') then
      raise exception 'This task is finished. Ask Taviron to reopen it.' using errcode = '42501';
    end if;
    if p_status in ('awaiting_customer', 'changes_requested', 'not_applicable', 'not_started') then
      raise exception 'Only Taviron can set that status.' using errcode = '42501';
    end if;
    if p_status = 'approved' and t.review_required then
      raise exception 'Taviron reviews this task. Submit it for review instead.' using errcode = '42501';
    end if;
    if p_status = 'submitted' and not t.review_required then
      raise exception 'This task needs no review. Mark it complete instead.' using errcode = '22023';
    end if;
    if t.status = 'submitted' and p_status not in ('in_progress') then
      raise exception 'This task is waiting for Taviron''s review. Withdraw it first to change it.' using errcode = '22023';
    end if;
  end if;

  if p_status in ('blocked', 'changes_requested') or (p_status = 'not_applicable' and t.required) then
    if length(v_note) < 3 then raise exception 'Say why (a few words).' using errcode = '22023'; end if;
  end if;
  if p_status in ('approved', 'submitted') then
    v_unmet := private.onboarding_unmet(t);
    if cardinality(v_unmet) > 0 then
      raise exception 'Waiting on: %.', array_to_string(v_unmet, ', ') using errcode = 'P0001';
    end if;
  end if;

  update public.onboarding_tasks set
    status = p_status,
    status_note = case when p_status in ('blocked', 'changes_requested', 'not_applicable', 'awaiting_customer') then v_note else '' end,
    submitted_at = case when p_status = 'submitted' then now() else submitted_at end,
    submitted_by = case when p_status = 'submitted' then auth.uid() else submitted_by end,
    decided_at = case when p_status in ('approved', 'not_applicable', 'changes_requested') then now() else decided_at end,
    decided_by = case when p_status in ('approved', 'not_applicable', 'changes_requested') then auth.uid() else decided_by end,
    updated_at = now()
  where id = t.id;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, from_status, to_status, body)
  values (t.company_id, t.id, auth.uid(), v_side, 'status', t.status, p_status, v_note);

  if p_staff then
    select * into t from public.onboarding_tasks where id = t.id;
    if p_status = 'changes_requested' then perform private.onboarding_notify(t, 'Changes requested: ' || t.title);
    elsif p_status = 'awaiting_customer' then perform private.onboarding_notify(t, 'Onboarding: your input is needed on ' || t.title);
    elsif p_status = 'approved' and t.side <> 'taviron' then perform private.onboarding_notify(t, 'Approved: ' || t.title);
    end if;
  end if;
  return jsonb_build_object('id', t.id, 'status', p_status, 'changed', true);
end;
$$;
revoke all on function private.onboarding_change(uuid, text, text, boolean) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Company side (settings.manage in the current company)
-- -----------------------------------------------------------------------------

create or replace function public.onboarding_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_company();
begin
  perform private.require_permission('settings.manage');
  return private.onboarding_json(v_company, false);
end;
$$;

create or replace function public.onboarding_set_status(p_task uuid, p_status text, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_company();
  perform private.require_permission('settings.manage');
  return private.onboarding_change(p_task, p_status, p_note, false);
end;
$$;

create or replace function public.onboarding_comment(p_task uuid, p_body text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  v_body text := btrim(coalesce(p_body, ''));
  v_id uuid;
begin
  perform private.require_company();
  perform private.require_permission('settings.manage');
  select * into t from public.onboarding_tasks where id = p_task;
  if not found or not private.onboarding_customer(t.company_id) then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if length(v_body) = 0 or length(v_body) > 2000 then raise exception 'Write a message of up to 2,000 characters.' using errcode = '22023'; end if;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  values (t.company_id, t.id, auth.uid(), 'customer', 'comment', v_body) returning id into v_id;
  return v_id;
end;
$$;

/** Assign a task to a person in the company (or nobody) and set or clear its due date. Company side or Taviron. */
create or replace function public.onboarding_assign(p_task uuid, p_user uuid, p_due date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  v_staff boolean := private.onboarding_staff();
  v_name text;
begin
  select * into t from public.onboarding_tasks where id = p_task for update;
  if not found or not (v_staff or private.onboarding_customer(t.company_id)) then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if not v_staff and t.side = 'taviron' then raise exception 'Taviron completes this task.' using errcode = '42501'; end if;
  if p_user is not null and not exists (select 1 from public.company_memberships m where m.company_id = t.company_id and m.user_id = p_user and m.active) then
    raise exception 'Choose an active person in this company.' using errcode = '22023';
  end if;
  if p_due is not null and (p_due < date '2020-01-01' or p_due > private.company_today(t.company_id) + 730) then
    raise exception 'Choose a due date within the next two years.' using errcode = '22023';
  end if;
  if t.assignee is not distinct from p_user and t.due_on is not distinct from p_due then return; end if;
  update public.onboarding_tasks set assignee = p_user, due_on = p_due, updated_at = now() where id = t.id;
  select coalesce(nullif(p.display_name, ''), p.full_name) into v_name from public.profiles p where p.id = p_user;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  values (t.company_id, t.id, auth.uid(), case when v_staff and not private.onboarding_customer(t.company_id) then 'taviron' else 'customer' end, 'assigned',
          concat_ws(' · ', case when p_user is null then 'Unassigned' else 'Assigned to ' || coalesce(v_name, 'a team member') end,
                    case when p_due is null then 'no due date' else 'due ' || to_char(p_due, 'Mon DD, YYYY') end));
  if p_user is not null and p_user is distinct from auth.uid() then
    select * into t from public.onboarding_tasks where id = t.id;
    perform private.onboarding_notify(t, 'Onboarding task assigned to you: ' || t.title);
  end if;
end;
$$;

