create or replace function public.platform_onboarding_generate(p_company uuid, p_integrations jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_added integer;
begin
  perform private.require_platform_admin();
  v_added := private.onboarding_generate(p_company, coalesce(p_integrations, '{}'::jsonb));
  perform private.platform_log('onboarding.generate', 'company', p_company::text,
    format('Onboarding checklist updated (%s task(s) added)', v_added), jsonb_build_object('added', v_added));
  return v_added;
end;
$$;

create or replace function public.platform_onboarding(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_platform_admin();
  return private.onboarding_json(p_company, true);
end;
$$;

/** One row per company with a checklist: the counts the console shows. */
create or replace function public.platform_onboarding_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_platform_admin();
  return coalesce((select jsonb_agg(jsonb_build_object('company_id', c.id, 'name', c.name, 'is_demo', c.is_demo,
      'summary', private.onboarding_summary(c.id)) order by c.name)
    from public.companies c where exists (select 1 from public.onboarding_tasks t where t.company_id = c.id)), '[]'::jsonb);
end;
$$;

create or replace function public.platform_onboarding_set_status(p_task uuid, p_status text, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_res jsonb;
  v_company uuid;
begin
  perform private.require_platform_admin();
  v_res := private.onboarding_change(p_task, p_status, p_note, true);
  if (v_res ->> 'changed')::boolean then
    select company_id into v_company from public.onboarding_tasks where id = p_task;
    perform private.platform_log('onboarding.status', 'company', v_company::text, format('Onboarding task set to %s', p_status),
      jsonb_build_object('task', p_task, 'status', p_status));
  end if;
  return v_res;
end;
$$;

create or replace function public.platform_onboarding_comment(p_task uuid, p_body text, p_internal boolean)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  v_body text := btrim(coalesce(p_body, ''));
  v_id uuid;
begin
  perform private.require_platform_admin();
  select * into t from public.onboarding_tasks where id = p_task;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if length(v_body) = 0 or length(v_body) > 2000 then raise exception 'Write a message of up to 2,000 characters.' using errcode = '22023'; end if;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body, internal)
  values (t.company_id, t.id, auth.uid(), 'taviron', 'comment', v_body, coalesce(p_internal, false)) returning id into v_id;
  if not coalesce(p_internal, false) then perform private.onboarding_notify(t, 'Taviron replied on ' || t.title); end if;
  return v_id;
end;
$$;

/** An in-app reminder about an open customer task (at most once a day per task). Nothing is emailed. */
create or replace function public.platform_onboarding_remind(p_task uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  v_n integer;
begin
  perform private.require_platform_admin();
  select * into t from public.onboarding_tasks where id = p_task for update;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if t.side = 'taviron' or t.status in ('approved', 'not_applicable', 'submitted') then
    raise exception 'Only open tasks the customer acts on can be reminded.' using errcode = '22023';
  end if;
  if t.last_reminded_at > now() - interval '1 day' then
    raise exception 'A reminder was already sent in the last 24 hours.' using errcode = '54000';
  end if;
  v_n := private.onboarding_notify(t, 'Reminder: ' || t.title || case when t.due_on is null then '' else ' (due ' || to_char(t.due_on, 'Mon DD') || ')' end);
  update public.onboarding_tasks set last_reminded_at = now() where id = t.id;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  values (t.company_id, t.id, auth.uid(), 'taviron', 'reminder', format('In-app reminder to %s %s.', v_n, case when v_n = 1 then 'person' else 'people' end));
  return v_n;
end;
$$;

/** Record that an import batch was staged from a task's document (the import itself keeps its own review and approval). */
create or replace function public.platform_onboarding_import_staged(p_document uuid, p_batch uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  d public.onboarding_documents%rowtype;
begin
  perform private.require_platform_admin();
  select * into d from public.onboarding_documents where id = p_document and status = 'uploaded';
  if not found then raise exception 'Document not found.' using errcode = 'P0002'; end if;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  values (d.company_id, d.task_id, auth.uid(), 'taviron', 'import',
          format('Import staged from %s for review (batch %s). Nothing is created until it is approved.', d.file_name, left(p_batch::text, 8)));
end;
$$;

/** The stored path of an uploaded document (for the server's signed download), for Taviron or the company side. */
create or replace function public.onboarding_document_path(p_document uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  d public.onboarding_documents%rowtype;
begin
  select * into d from public.onboarding_documents where id = p_document and status = 'uploaded';
  if not found or not (private.onboarding_staff() or private.onboarding_customer(d.company_id)) then
    raise exception 'Document not found.' using errcode = 'P0002';
  end if;
  return jsonb_build_object('object_path', d.object_path, 'file_name', d.file_name, 'mime_type', d.mime_type, 'company_id', d.company_id, 'task_id', d.task_id);
end;
$$;

-- -----------------------------------------------------------------------------
-- Documents (private Storage bucket `onboarding-documents`)
-- -----------------------------------------------------------------------------

create or replace function private.can_upload_onboarding_document(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.onboarding_documents d
    where d.object_path = p_name and d.status = 'pending' and d.created_by = auth.uid()
      and (private.onboarding_staff() or private.onboarding_customer(d.company_id)))
$$;

create or replace function private.can_read_onboarding_document(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.onboarding_documents d
    where d.object_path = p_name and d.status = 'uploaded'
      and (private.onboarding_staff() or private.onboarding_customer(d.company_id)))
$$;
grant execute on function private.can_upload_onboarding_document(text), private.can_read_onboarding_document(text) to authenticated;

create or replace function private.setup_onboarding_document_storage()
returns void
language plpgsql
set search_path = ''
as $$
begin
  if to_regclass('storage.objects') is null or to_regclass('storage.buckets') is null then
    raise exception 'Supabase Storage is not installed in this database.';
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('onboarding-documents', 'onboarding-documents', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png', 'text/csv'])
  on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  drop policy if exists onboarding_documents_insert on storage.objects;
  drop policy if exists onboarding_documents_read on storage.objects;
  create policy onboarding_documents_insert on storage.objects for insert to authenticated
    with check (bucket_id = 'onboarding-documents' and private.can_upload_onboarding_document(name));
  create policy onboarding_documents_read on storage.objects for select to authenticated
    using (bucket_id = 'onboarding-documents' and private.can_read_onboarding_document(name));
  -- No update or delete policies: nobody replaces or removes a file from the app.
end;
$$;

do $$
begin
  if to_regclass('storage.objects') is not null then
    perform private.setup_onboarding_document_storage();
  else
    raise notice 'Supabase Storage is not installed: run select private.setup_onboarding_document_storage(); after enabling it.';
  end if;
end;
$$;

/** Reserve a path for a document on a task. Idempotent per upload key. */
create or replace function public.onboarding_begin_document(p_task uuid, p_upload_key uuid, p_file_name text, p_mime text, p_size integer, p_sha256 text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.onboarding_tasks%rowtype;
  d public.onboarding_documents%rowtype;
  v_staff boolean := private.onboarding_staff();
  v_id uuid := gen_random_uuid();
  v_name text := left(regexp_replace(trim(coalesce(p_file_name, '')), '[\x00-\x1f/\\]', '_', 'g'), 200);
begin
  select * into t from public.onboarding_tasks where id = p_task;
  if not found or not (v_staff or private.onboarding_customer(t.company_id)) then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if p_upload_key is null then raise exception 'Missing upload key.' using errcode = '22023'; end if;
  select * into d from public.onboarding_documents where company_id = t.company_id and upload_key = p_upload_key;
  if found then
    if d.created_by is distinct from auth.uid() or d.task_id <> t.id then raise exception 'This upload was already used.' using errcode = '42501'; end if;
    return jsonb_build_object('document_id', d.id, 'object_path', d.object_path, 'status', d.status);
  end if;
  if t.status in ('approved', 'not_applicable') then raise exception 'This task is finished. Ask Taviron to reopen it to add files.' using errcode = '22023'; end if;
  if p_mime is null or p_mime not in ('application/pdf', 'image/jpeg', 'image/png', 'text/csv') then
    raise exception 'Only PDF, JPEG, PNG or CSV files can be added.' using errcode = '22023';
  end if;
  if p_size is null or p_size < 1 or p_size > 10485760 then raise exception 'A file must be 10 MB or smaller.' using errcode = '22023'; end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'Invalid file checksum.' using errcode = '22023'; end if;
  if exists (select 1 from public.onboarding_documents where task_id = t.id and sha256 = p_sha256 and status = 'uploaded') then
    raise exception 'This exact file is already on this task.' using errcode = '23505';
  end if;
  if (select count(*) from public.onboarding_documents where task_id = t.id and status = 'uploaded') >= 20 then
    raise exception 'A task holds at most 20 files.' using errcode = '22023';
  end if;
  if (select count(*) from public.onboarding_documents where created_by = auth.uid() and created_at > now() - interval '1 hour') >= 30 then
    raise exception 'Too many uploads in the last hour. Try again later.' using errcode = '54000';
  end if;
  if length(v_name) = 0 then v_name := 'file'; end if;
  insert into public.onboarding_documents (id, company_id, task_id, object_path, file_name, mime_type, size_bytes, sha256, upload_key, side, created_by)
  values (v_id, t.company_id, t.id,
          t.company_id || '/onboarding/' || v_id || case p_mime when 'application/pdf' then '.pdf' when 'image/jpeg' then '.jpg'
                                                               when 'image/png' then '.png' else '.csv' end,
          v_name, p_mime, p_size, p_sha256, p_upload_key, case when v_staff and not private.onboarding_customer(t.company_id) then 'taviron' else 'customer' end, auth.uid())
  returning * into d;
  return jsonb_build_object('document_id', d.id, 'object_path', d.object_path, 'status', d.status);
end;
$$;

/** After the upload: the stored object must match what was declared; then the document shows on the task. */
create or replace function public.onboarding_confirm_document(p_document uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  d public.onboarding_documents%rowtype;
  v_size bigint;
  v_mime text;
begin
  select * into d from public.onboarding_documents where id = p_document and created_by = auth.uid() for update;
  if not found or not (private.onboarding_staff() or private.onboarding_customer(d.company_id)) then raise exception 'File not found.' using errcode = 'P0002'; end if;
  if d.status = 'uploaded' then return jsonb_build_object('document_id', d.id, 'status', d.status); end if;
  if d.status <> 'pending' then raise exception 'This file was removed. Add it again.' using errcode = '22023'; end if;
  select (o.metadata ->> 'size')::bigint, o.metadata ->> 'mimetype' into v_size, v_mime
  from storage.objects o where o.bucket_id = 'onboarding-documents' and o.name = d.object_path;
  if not found then raise exception 'The file did not arrive. Try again.' using errcode = 'P0001'; end if;
  if v_size is distinct from d.size_bytes or split_part(v_mime, ';', 1) is distinct from d.mime_type then
    raise exception 'The stored file does not match what was sent. Try again.' using errcode = 'P0001';
  end if;
  update public.onboarding_documents set status = 'uploaded', uploaded_at = now() where id = d.id;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  values (d.company_id, d.task_id, auth.uid(), d.side, 'document', 'Added ' || d.file_name);
  return jsonb_build_object('document_id', d.id, 'status', 'uploaded');
end;
$$;

-- -----------------------------------------------------------------------------
-- Demo companies: sample checklist in varied states (fictional; is_demo only; idempotent)
-- -----------------------------------------------------------------------------

create or replace function public.onboarding_demo_samples()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_company();
  v_added integer;
  v_staff uuid;
begin
  perform private.require_permission('settings.manage');
  if not exists (select 1 from public.companies where id = v_company and is_demo) then
    raise exception 'Sample onboarding is only for demo companies.' using errcode = '42501';
  end if;
  if exists (select 1 from public.onboarding_tasks where company_id = v_company) then return 0; end if;
  v_added := private.onboarding_generate(v_company, '{"routing": false, "ai": false}'::jsonb);
  -- A fictional mid-onboarding picture: finished, waiting on review, changes requested, blocked, waiting on the customer.
  update public.onboarding_tasks set status = 'approved', decided_at = now() - interval '6 days'
    where company_id = v_company and key in ('agreement', 'company_profile', 'people');
  update public.onboarding_tasks set status = 'approved', decided_at = now() - interval '2 days'
    where company_id = v_company and key = 'materials';
  update public.onboarding_tasks set status = 'submitted', submitted_at = now() - interval '1 day'
    where company_id = v_company and key = 'customers';
  update public.onboarding_tasks set status = 'changes_requested', decided_at = now() - interval '1 day',
    status_note = 'Three trucks have no capacity yet (sample). Add weight or volume capacity and submit again.'
    where company_id = v_company and key = 'trucks';
  update public.onboarding_tasks set status = 'blocked',
    status_note = 'Waiting for medical card copies from two drivers (sample).', due_on = private.company_today(v_company) - 2
    where company_id = v_company and key = 'drivers';
  update public.onboarding_tasks set status = 'awaiting_customer', status_note = 'Pick two dates for the session (sample).',
    due_on = private.company_today(v_company) + 5
    where company_id = v_company and key = 'training_dispatch';
  update public.onboarding_tasks set status = 'not_applicable', status_note = 'Demo company: no portal setup needed (sample).'
    where company_id = v_company and key = 'portal' and not required;
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, from_status, to_status, body)
  select company_id, id, null, 'system', 'status', 'not_started', status, 'Sample state for the demo company.'
  from public.onboarding_tasks where company_id = v_company and status <> 'not_started';
  insert into public.onboarding_events (company_id, task_id, actor, actor_side, kind, body)
  select company_id, id, null, 'taviron', 'comment', 'Thanks — the materials file looked good. We imported 12 materials after your review (sample).'
  from public.onboarding_tasks where company_id = v_company and key = 'materials';
  return v_added;
end;
$$;

revoke all on function public.onboarding_state(), public.onboarding_set_status(uuid, text, text), public.onboarding_comment(uuid, text),
  public.onboarding_assign(uuid, uuid, date), public.platform_onboarding_generate(uuid, jsonb), public.platform_onboarding(uuid),
  public.platform_onboarding_overview(), public.platform_onboarding_set_status(uuid, text, text),
  public.platform_onboarding_comment(uuid, text, boolean), public.platform_onboarding_remind(uuid),
  public.platform_onboarding_import_staged(uuid, uuid), public.onboarding_document_path(uuid),
  public.onboarding_begin_document(uuid, uuid, text, text, integer, text), public.onboarding_confirm_document(uuid),
  public.onboarding_demo_samples() from public, anon;
grant execute on function public.onboarding_state(), public.onboarding_set_status(uuid, text, text), public.onboarding_comment(uuid, text),
  public.onboarding_assign(uuid, uuid, date), public.platform_onboarding_generate(uuid, jsonb), public.platform_onboarding(uuid),
  public.platform_onboarding_overview(), public.platform_onboarding_set_status(uuid, text, text),
  public.platform_onboarding_comment(uuid, text, boolean), public.platform_onboarding_remind(uuid),
  public.platform_onboarding_import_staged(uuid, uuid), public.onboarding_document_path(uuid),
  public.onboarding_begin_document(uuid, uuid, text, text, integer, text), public.onboarding_confirm_document(uuid),
  public.onboarding_demo_samples() to authenticated;
